const form=document.querySelector('#config-form');
const toast=document.querySelector('#toast');
const numberFields=new Set(['mail_expiry_ms','count','concurrency','stagger_ms','chatgpt_step_delay_ms','probe_delay_sec','probe_concurrency','probe_stagger_ms','import_concurrency','import_stagger_ms','sub2api_group_id','sub2api_xai_group_id']);
let config={};
let outputPaths=[];
let mailPresets={};
let mailDrafts={};
let activeMailProvider='yyds';
let performanceProfile={};
let monitorState={batches:[],sessions:[]};
let hotmailAvailableCount=0;
let manualRegistrationCount=1;
let manualRegistrationConcurrency=1;
let activeConfigModule='registration';
let rotationState={page:1,pageSize:20,total:0,pages:1,items:[],selected:new Set(),loading:false};
const concurrencyWarningKey='progrok_concurrency_warning_ack';
const configModuleKey='progrok_active_config_module';
const configModuleNames={registration:'注册配置',mail:'邮箱配置',proxy:'代理配置',import:'自动导入配置',probe:'测活配置',rotation:'账号轮询'};

function notify(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
function setActiveConfigModule(name,persist=true){const target=configModuleNames[name]?name:'registration';activeConfigModule=target;const rotating=target==='rotation';document.querySelectorAll('[data-config-module]').forEach(module=>{const active=module.dataset.configModule===target;module.hidden=!active;module.classList.toggle('active',active)});document.querySelectorAll('[data-config-tab]').forEach(button=>{const active=button.dataset.configTab===target;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});document.querySelector('.workspace')?.classList.toggle('rotation-layout',rotating);const sideColumn=document.querySelector('.side-column');if(sideColumn)sideColumn.hidden=rotating;document.querySelector(`[data-config-tab="${target}"]`)?.scrollIntoView({block:'nearest',inline:'center'});document.querySelector('.config-toolbar-title').textContent=configModuleNames[target];document.querySelector('.config-scroll').scrollTop=0;updateToolbarActions();if(rotating)refreshRotation();if(persist){try{localStorage.setItem(configModuleKey,target)}catch{}}}
function updateToolbarActions(){const probing=activeConfigModule==='probe';const rotating=activeConfigModule==='rotation';const startButton=document.querySelector('#start');const pauseButton=document.querySelector('#pause-current');const format=document.querySelector('.toolbar-format');const saveButton=document.querySelector('#save');format.hidden=rotating;saveButton.hidden=rotating;pauseButton.hidden=rotating;startButton.textContent=rotating?'立即全量探活':probing?'开始测活':'开始注册';startButton.disabled=probing?!document.querySelector('#probe-batch')?.value:false;if(rotating)return;if(probing)updateProbePauseButton(monitorState.batches);else updatePauseButton(monitorState.batches)}
async function api(url,options={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...options});let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data.detail?.error||data.detail||data.error||`HTTP ${r.status}`);return data}
function readForm(){if(activeMailProvider!=='hotmail_local')mailDrafts[activeMailProvider]=readMailFields();const out={...config};for(const [key,value] of new FormData(form).entries())out[key]=numberFields.has(key)?Number(value):value;out.mail_provider_configs={...(config.mail_provider_configs||{}),...mailDrafts};out.auto_tune_enabled=Boolean(form.elements.namedItem('auto_tune_enabled')?.checked);out.grok_headless=!Boolean(document.querySelector('#grok-browser-visible')?.checked);out.chatgpt_headless=!Boolean(document.querySelector('#chatgpt-browser-visible')?.checked);out.probe_delay_sec=Number(out.probe_delay_sec||0);return out}
function fillForm(data){config=data;manualRegistrationCount=Math.max(1,Number(data.count)||1);manualRegistrationConcurrency=Math.max(1,Number(data.concurrency)||1);const groupNameFields={sub2api_group_id:'sub2api_group_name',sub2api_xai_group_id:'sub2api_xai_group_name'};for(const [key,value] of Object.entries(data)){const el=form.elements.namedItem(key);if(!el)continue;if(groupNameFields[key]&&Number(value)>0&&![...el.options].some(option=>Number(option.value)===Number(value))){el.add(new Option(data[groupNameFields[key]]||`分组 ${value}`,String(value)))}if(el.type==='checkbox')el.checked=Boolean(value);else el.value=value??''}const grokBrowserVisible=document.querySelector('#grok-browser-visible');if(grokBrowserVisible)grokBrowserVisible.checked=!Boolean(data.grok_headless);const chatgptBrowserVisible=document.querySelector('#chatgpt-browser-visible');if(chatgptBrowserVisible)chatgptBrowserVisible.checked=!Boolean(data.chatgpt_headless);updateImportTargetFields();updateTargetFields();updateMailProviderFields()}
function readMailFields(){return {mail_base_url:form.elements.namedItem('mail_base_url').value,mail_api_key:form.elements.namedItem('mail_api_key').value,mail_domain:form.elements.namedItem('mail_domain').value}}
function applyMailFields(values={}){for(const key of ['mail_base_url','mail_api_key','mail_domain'])form.elements.namedItem(key).value=values[key]??''}
function switchMailProvider(){const selected=form.elements.namedItem('mail_provider').value;if(activeMailProvider!=='hotmail_local'){manualRegistrationCount=Math.max(1,Number(form.elements.namedItem('count').value)||1);manualRegistrationConcurrency=Math.max(1,Number(form.elements.namedItem('concurrency').value)||1);mailDrafts[activeMailProvider]=readMailFields()}activeMailProvider=selected;if(selected==='hotmail_local')form.elements.namedItem('concurrency').value='1';else{const values=mailDrafts[selected]||config.mail_provider_configs?.[selected]||mailPresets[selected]||{};applyMailFields(values);mailDrafts[selected]=readMailFields()}updateMailProviderFields();if(selected==='hotmail_local')loadHotmailAccounts()}
function clampRegistrationConcurrency(){const count=Math.max(0,Number(form.elements.namedItem('count').value)||0);const concurrency=form.elements.namedItem('concurrency');const max=count>0?Math.min(10,count):0;concurrency.min=count>0?'1':'0';concurrency.max=String(max);const current=Number(concurrency.value)||0;concurrency.value=String(count>0?Math.min(max,Math.max(1,current)):0);document.querySelector('#registration-concurrency-label').textContent=count>0?`并发数（最多 ${max}）`:'并发数（暂无可用邮箱）'}
function syncRegistrationCapacity(){const local=form.elements.namedItem('mail_provider').value==='hotmail_local';const count=form.elements.namedItem('count');const concurrency=form.elements.namedItem('concurrency');const wasLocal=count.readOnly;document.querySelector('#registration-count-label').textContent=local?'可用邮箱数量':'注册数量';count.readOnly=local;count.min=local?'0':'1';if(local){count.value=String(hotmailAvailableCount);if(hotmailAvailableCount>0&&Number(concurrency.value)<=0)concurrency.value='1'}else if(wasLocal){count.value=String(manualRegistrationCount);concurrency.value=String(manualRegistrationConcurrency)}clampRegistrationConcurrency()}
function updateMailProviderFields(){const local=form.elements.namedItem('mail_provider').value==='hotmail_local';document.querySelectorAll('[data-mail-standard]').forEach(el=>{el.hidden=local});document.querySelector('#hotmail-local-panel').hidden=!local;syncRegistrationCapacity()}
function hotmailAccountHtml(item){const accountStatus=item.reserved?'使用中':item.used?'已使用':item.failed?'注册失败':item.mail_healthy===true?'测活通过':item.mail_healthy===false?'测活失败':'等待测活';const action=item.failed?`<button type="button" data-hotmail-action="restore" data-id="${escapeHtml(item.id)}">允许复用</button>`:item.used?`<button type="button" data-hotmail-action="restore" data-id="${escapeHtml(item.id)}">恢复未用</button>`:'';const failureDetail=item.failed&&item.failure_reason?`<small class="hotmail-failure">注册失败：${escapeHtml(item.failure_reason)}</small>`:'';const healthDetail=item.mail_healthy===false&&item.mail_health_error?`<small class="hotmail-health-error">测活失败：${escapeHtml(item.mail_health_error)}</small>`:'';const statusClass=item.failed?'failed':item.used?'used':item.reserved?'reserved':item.mail_healthy===true?'healthy':item.mail_healthy===false?'unhealthy':'unchecked';return `<div class="hotmail-account"><div><strong>${escapeHtml(item.email)}</strong><small>Client ID ${escapeHtml(item.client_id_masked||'--')} · Refresh Token ${escapeHtml(item.refresh_token_masked||'--')}</small>${failureDetail}${healthDetail}</div><span class="hotmail-status ${statusClass}">${accountStatus}</span><div class="hotmail-actions">${action}<button type="button" data-hotmail-action="probe" data-id="${escapeHtml(item.id)}">重新测活</button><button type="button" class="danger-button" data-hotmail-action="delete" data-id="${escapeHtml(item.id)}">删除</button></div></div>`}
function renderHotmailAccounts(pool={}){hotmailAvailableCount=Math.max(0,Number(pool.available)||0);document.querySelector('#hotmail-pool-summary').textContent=`账户池：共 ${pool.total||0} · 可用 ${hotmailAvailableCount} · 测活通过 ${pool.healthy||0} · 测活失败 ${pool.unhealthy||0} · 未测活 ${pool.unchecked||0} · 注册失败 ${pool.failed||0} · 已用 ${pool.used||0}`;const list=document.querySelector('#hotmail-account-list');list.innerHTML=(pool.accounts||[]).length?pool.accounts.map(hotmailAccountHtml).join(''):'<div class="empty">尚未导入微软邮箱账号</div>';syncRegistrationCapacity()}
async function loadHotmailAccounts(){try{renderHotmailAccounts(await api('/api/mail/hotmail/accounts'))}catch(e){document.querySelector('#hotmail-pool-summary').textContent=`账户池读取失败：${e.message}`}}
async function importHotmailAccounts(){const button=document.querySelector('#import-hotmail-accounts');const text=document.querySelector('#hotmail-import-text').value;if(!text.trim()){notify('请先粘贴微软邮箱账号');return}button.disabled=true;button.textContent='正在导入并测活…';try{const base_url=form.elements.namedItem('hotmail_local_base_url').value;const result=await api('/api/mail/hotmail/accounts/import',{method:'POST',body:JSON.stringify({text,base_url})});renderHotmailAccounts(result.pool);document.querySelector('#hotmail-import-text').value='';notify(`导入并测活完成：新增 ${result.added}，更新 ${result.updated}，通过 ${result.probe?.passed||0}，失败 ${result.probe?.failed||0}，无效 ${result.invalid}`)}catch(e){notify(`导入或测活失败：${e.message}`)}finally{button.disabled=false;button.textContent='导入并自动测活'}}
async function probeAllHotmailAccounts(){const button=document.querySelector('#probe-hotmail-accounts');button.disabled=true;button.textContent='正在测活…';try{const base_url=form.elements.namedItem('hotmail_local_base_url').value;const result=await api('/api/mail/hotmail/accounts/probe',{method:'POST',body:JSON.stringify({base_url})});renderHotmailAccounts(result.pool);notify(`邮箱测活完成：通过 ${result.passed||0}，失败 ${result.failed||0}`)}catch(e){notify(`邮箱测活失败：${e.message}`)}finally{button.disabled=false;button.textContent='全部重新测活'}}
async function deleteUsedHotmailAccounts(){if(!window.confirm('确定删除账户池中所有“已使用”邮箱吗？\n\n正在被任务占用的邮箱会自动跳过，此操作不可撤销。'))return;const button=document.querySelector('#delete-used-hotmail-accounts');button.disabled=true;button.textContent='正在删除…';try{const result=await api('/api/mail/hotmail/accounts/used',{method:'DELETE'});renderHotmailAccounts(result.pool);notify(`已删除 ${result.deleted||0} 个已用邮箱${result.skipped_reserved?`，跳过 ${result.skipped_reserved} 个使用中的邮箱`:''}`)}catch(e){notify(`删除已用邮箱失败：${e.message}`)}finally{button.disabled=false;button.textContent='删除已用'}}
async function testHotmailHelper(){const button=document.querySelector('#test-hotmail-helper');const state=document.querySelector('#hotmail-helper-state');button.disabled=true;state.textContent='检测中…';state.className='detect-state';try{const result=await api('/api/mail/hotmail/test',{method:'POST',body:JSON.stringify(readForm())});state.textContent=result.ok?'● 在线':'● 异常';state.className=`detect-state ${result.ok?'online':'offline'}`;notify(result.ok?`本地邮箱助手在线：${result.service||'hotmail-helper'}`:'本地邮箱助手响应异常')}catch(e){state.textContent='● 离线';state.className='detect-state offline';notify(`助手检测失败：${e.message}`)}finally{button.disabled=false}}
async function handleHotmailAccountAction(event){const button=event.target.closest('[data-hotmail-action]');if(!button)return;const action=button.dataset.hotmailAction;const id=button.dataset.id;if(action==='delete'&&!window.confirm('确定从账户池删除这个邮箱吗？'))return;button.disabled=true;try{let result;if(action==='probe'){button.textContent='测活中…';const base_url=form.elements.namedItem('hotmail_local_base_url').value;result=await api(`/api/mail/hotmail/accounts/${encodeURIComponent(id)}/probe`,{method:'POST',body:JSON.stringify({base_url})})}else{const options=action==='delete'?{method:'DELETE'}:{method:'PATCH',body:JSON.stringify({used:false})};result=await api(`/api/mail/hotmail/accounts/${encodeURIComponent(id)}`,options)}renderHotmailAccounts(result.pool);notify(action==='delete'?'邮箱已删除':action==='probe'?(result.ok?'邮箱测活通过':`邮箱测活失败：${result.error||'未知原因'}`):'邮箱已恢复为可复用状态')}catch(e){notify(`操作失败：${e.message}`)}finally{button.disabled=false}}
function updateImportTargetFields(){const target=form.elements.namedItem('auto_import_target').value;const subAuth=form.elements.namedItem('sub2api_auth_mode').value;const registrationTarget=form.elements.namedItem('registration_target').value;document.querySelectorAll('[data-import-target]').forEach(el=>{const targetVisible=el.dataset.importTarget===target;const authVisible=!el.dataset.sub2Auth||el.dataset.sub2Auth===subAuth;const chatgptVisible=!el.hasAttribute('data-chatgpt-only')||registrationTarget==='chatgpt';const grokVisible=!el.hasAttribute('data-grok-only')||registrationTarget==='grok';el.hidden=!(targetVisible&&authVisible&&chatgptVisible&&grokVisible)})}
function updateTargetFields(){const target=form.elements.namedItem('registration_target').value;document.querySelectorAll('[data-target]').forEach(el=>{const targetVisible=el.dataset.target===target;el.hidden=!targetVisible});document.querySelectorAll('#config-form .section-title').forEach(el=>{if(el.dataset.target){el.hidden=el.dataset.target!==target}});document.querySelectorAll('#config-form .grid').forEach(el=>{if(el.dataset.target){el.hidden=el.dataset.target!==target}});updateImportTargetFields();updateProbeBatches(monitorState.batches)}
function sub2APIGroupControls(){const chatgpt=form.elements.namedItem('registration_target').value==='chatgpt';return chatgpt?{button:document.querySelector('#load-sub2api-chatgpt-groups'),state:document.querySelector('#sub2api-group-state'),select:form.elements.namedItem('sub2api_group_id'),idKey:'sub2api_group_id',nameKey:'sub2api_group_name'}:{button:document.querySelector('#load-sub2api-xai-groups'),state:document.querySelector('#sub2api-xai-group-state'),select:form.elements.namedItem('sub2api_xai_group_id'),idKey:'sub2api_xai_group_id',nameKey:'sub2api_xai_group_name'}}
function sub2APIGroupOptionName(group){const platform=String(group.platform||'').trim();return platform?`[${platform}] ${group.name}`:String(group.name||`分组 ${group.id}`)}
async function loadSub2APIGroups(){const controls=sub2APIGroupControls();const {button,state,select,idKey}=controls;const current=Number(select.value||config[idKey]||0);button.disabled=true;button.textContent='正在获取…';state.textContent='正在连接 Sub2API 并读取全部现有分组';try{const settings=readForm();const result=await api('/api/sub2api/groups',{method:'POST',body:JSON.stringify({sub2api_base_url:settings.sub2api_base_url,sub2api_auth_mode:settings.sub2api_auth_mode,sub2api_admin_email:settings.sub2api_admin_email,sub2api_admin_password:settings.sub2api_admin_password,sub2api_api_key:settings.sub2api_api_key})});const groups=result.groups||[];select.innerHTML='<option value="0">使用 Sub2API 默认分组</option>'+groups.map(group=>`<option value="${group.id}">${escapeHtml(sub2APIGroupOptionName(group))}</option>`).join('');if([...select.options].some(option=>Number(option.value)===current))select.value=String(current);else if(groups.length===1)select.value=String(groups[0].id);syncSub2APIGroupName();state.textContent=groups.length?`已获取 ${groups.length} 个 Sub2API 分组，可直接选择绑定`:'站点当前没有分组，将使用默认分组';notify(`Sub2API 分组获取完成：${groups.length} 个`)}catch(e){state.textContent=`分组获取失败：${e.message}`;notify(`分组获取失败：${e.message}`)}finally{button.disabled=false;button.textContent='自动获取分组'}}
function syncSub2APIGroupName(){const {select,nameKey}=sub2APIGroupControls();const selected=select.options[select.selectedIndex];form.elements.namedItem(nameKey).value=Number(select.value)>0?(selected?.textContent||''):''}
function syncFormatFromTarget(){form.elements.namedItem('registration_json_format').value=form.elements.namedItem('auto_import_target').value;updateImportTargetFields()}
function syncTargetFromFormat(){form.elements.namedItem('auto_import_target').value=form.elements.namedItem('registration_json_format').value;updateImportTargetFields()}
async function togglePaths(forceOpen=false){const pop=document.querySelector('#paths-popover');const shouldOpen=forceOpen||pop.hidden;if(!shouldOpen){pop.hidden=true;return}document.querySelector('#download-popover').hidden=true;pop.hidden=false;try{const r=await api('/api/output-paths');outputPaths=r.items||[];document.querySelector('#paths-list').innerHTML=outputPaths.map((item,index)=>`<div class="path-row"><div><span>${escapeHtml(item.label)}</span><code>${escapeHtml(item.path)}</code></div><button type="button" class="copy-path" data-index="${index}">复制</button></div>`).join('')}catch(e){document.querySelector('#paths-list').innerHTML=`<div class="paths-error">${escapeHtml(e.message)}</div>`}}
function toggleDownload(){const pop=document.querySelector('#download-popover');const shouldOpen=pop.hidden;document.querySelector('#paths-popover').hidden=true;pop.hidden=!shouldOpen}
async function copyOutputPath(index){const item=outputPaths[index];if(!item)return;try{await navigator.clipboard.writeText(item.path);notify(`已复制：${item.label}`)}catch{notify(`路径：${item.path}`)}}

function renderPerformance(profile={}){performanceProfile=profile;const el=document.querySelector('#performance-profile');const physical=profile.physical_cores||'--';const memory=profile.memory_available_gb??'--';const recommended=profile.recommended_concurrency||profile.effective_cap||'--';el.innerHTML=`检测：${escapeHtml(physical)} 个物理核心 · 可用内存 ${escapeHtml(memory)} GB · 浏览器建议并发上限 <strong>${escapeHtml(recommended)}</strong> · 注册并发以手动配置为准`}
async function loadPerformance(){try{renderPerformance(await api('/api/performance?provider=browser'))}catch(e){document.querySelector('#performance-profile').textContent=`性能检测失败：${e.message}`}}
async function load(){try{const [saved,presets]=await Promise.all([api('/api/config'),api('/api/mail/provider-presets')]);mailPresets=presets.providers||{};mailDrafts={...(saved.mail_provider_configs||{})};activeMailProvider=saved.mail_provider||'yyds';fillForm(saved);if(activeMailProvider!=='hotmail_local'){const values=mailDrafts[activeMailProvider]||mailPresets[activeMailProvider]||readMailFields();applyMailFields(values);mailDrafts[activeMailProvider]=readMailFields()}if(activeMailProvider==='hotmail_local')await loadHotmailAccounts();if(!String(saved.proxy||'').trim())await detectProxy(false,true);await loadPerformance();await checkHealth();await refresh()}catch(e){notify(e.message)}}
async function checkHealth(){const el=document.querySelector('#health');try{const h=await api('/api/health');el.textContent=h.ok?'服务就绪':'注册引擎异常';el.className=`badge ${h.ok?'ok':'bad'}`}catch{el.textContent='服务异常';el.className='badge bad'}}
async function detectSolver(showToast=true){const state=document.querySelector('#solver-state');const btn=document.querySelector('#detect-solver');state.textContent='检测中…';state.className='detect-state';btn.disabled=true;try{const r=await api('/api/solver/detect');if(r.found){const input=form.elements.namedItem('local_solver_url');input.value=r.url;config.local_solver_url=r.url;state.textContent='● 在线';state.className='detect-state online';if(showToast)notify(`已检测到 Solver：${r.url}`)}else{state.textContent='● 未检测到';state.className='detect-state offline';if(showToast)notify(r.error||'未检测到本地 Solver')}}catch(e){state.textContent='● 检测失败';state.className='detect-state offline';if(showToast)notify(`检测失败：${e.message}`)}finally{btn.disabled=false}}
async function detectProxy(showToast=true,onlyWhenEmpty=false){const btn=document.querySelector('#detect-proxy');const input=form.elements.namedItem('proxy');if(onlyWhenEmpty&&String(input.value||'').trim())return;btn.disabled=true;btn.textContent='检测中…';try{const r=await api('/api/proxy/detect');if(!r.found){if(showToast)notify(r.error||'未检测到本机代理');return}if(onlyWhenEmpty&&String(input.value||'').trim())return;input.value=r.proxy||'';const username=form.elements.namedItem('proxy_username');const password=form.elements.namedItem('proxy_password');if(!username.value&&r.proxy_username)username.value=r.proxy_username;if(!password.value&&r.proxy_password)password.value=r.proxy_password;if(showToast)notify(`已填写代理：${r.source||'本机代理'}，保存配置后生效`)}catch(e){if(showToast)notify(`代理检测失败：${e.message}`)}finally{btn.disabled=false;btn.textContent='检测本机代理'}}
async function save(){const btn=document.querySelector('#save');btn.disabled=true;try{const r=await api('/api/config',{method:'PUT',body:JSON.stringify(readForm())});fillForm(r.config);notify('配置已保存')}catch(e){notify(`保存失败：${e.message}`)}finally{btn.disabled=false}}
function concurrencyWarningRemembered(){try{return localStorage.getItem(concurrencyWarningKey)==='1'}catch{return false}}
function showConcurrencyWarning(concurrency){const modal=document.querySelector('#concurrency-warning');const physical=performanceProfile.physical_cores||'--';const memory=performanceProfile.memory_available_gb??'--';const solver=performanceProfile.solver_threads||'--';const recommended=Number(performanceProfile.recommended_concurrency||performanceProfile.effective_cap||0);document.querySelector('#concurrency-warning-value').textContent=String(concurrency);document.querySelector('#concurrency-performance-summary').textContent=`${physical} 个物理核心 · 可用内存 ${memory} GB · Solver ${solver} 线程`;document.querySelector('#concurrency-performance-advice').textContent=recommended?`机器建议注册并发不超过 ${recommended}；当前设置${concurrency>recommended?`已超出 ${concurrency-recommended}`:'未超过建议上限'}。`:'暂未取得机器建议上限，请优先使用较低并发。';modal.hidden=false;return new Promise(resolve=>{const finish=choice=>{modal.hidden=true;document.querySelector('#concurrency-warning-cancel').onclick=null;document.querySelector('#concurrency-warning-continue').onclick=null;document.querySelector('#concurrency-warning-remember').onclick=null;resolve(choice)};document.querySelector('#concurrency-warning-cancel').onclick=()=>finish('cancel');document.querySelector('#concurrency-warning-continue').onclick=()=>finish('continue');document.querySelector('#concurrency-warning-remember').onclick=()=>finish('remember')})}
async function start(e){e.preventDefault();if(activeConfigModule==='rotation'){await startAllRotationProbe();return}if(activeConfigModule==='probe'){await startBatchProbe();return}clampRegistrationConcurrency();const settings=readForm();if(settings.count<1){notify(settings.mail_provider==='hotmail_local'?'微软邮箱账户池没有可用邮箱，请先导入或恢复邮箱':'注册数量必须大于 0');return}if(settings.concurrency>settings.count){notify('并发数不能大于注册数量');return}if(settings.concurrency>3&&!concurrencyWarningRemembered()){const choice=await showConcurrencyWarning(settings.concurrency);if(choice==='cancel')return;if(choice==='remember'){try{localStorage.setItem(concurrencyWarningKey,'1')}catch{}}}const btn=document.querySelector('#start');btn.disabled=true;btn.textContent='正在创建任务…';try{const r=await api('/api/register',{method:'POST',body:JSON.stringify(settings)});notify(r.batch_id?'批量任务已启动':'注册任务已启动');await refresh()}catch(e){notify(`启动失败：${e.message}`)}finally{btn.disabled=false;btn.textContent=activeConfigModule==='probe'?'开始测活':'开始注册'}}

function terminal(status){return ['imported','success','completed','error','failed','cancelled','stopped','done','partial','protocol_error','protocol_blocked','account_error','expired'].includes(String(status).toLowerCase())}
const statusNames={queued:'排队中',starting:'正在启动',started:'已启动',running:'注册中',pausing:'正在暂停',paused:'已暂停',resuming:'正在继续',waiting_solver:'等待过盾服务',solving_turnstile:'正在过盾',registering:'正在注册',waiting_email:'等待邮箱验证码',creating_account:'正在创建账号',fetching_sso:'正在获取 Session',importing:'正在转换认证',launching:'正在启动浏览器',navigating:'正在打开注册页',signup_page:'正在定位注册入口',email_filling:'正在填写邮箱',email_submitted:'邮箱已提交',verification:'正在处理验证码',code_received:'已收到验证码',profile:'正在填写个人信息',completion:'等待注册完成',session_extracting:'正在提取会话',converting:'正在生成 Agent Identity',converted:'JSON 转换完成',probe_queued:'测活排队中',probing:'账号测活中',probe_retry_pending:'测活待复检',probe_uncertain:'测活检测异常',probe_complete:'测活完成',import_queued:'导入排队中',auto_importing:'正在导入站点',imported:'全部流程成功',success:'成功',completed:'已完成',done:'已完成',partial:'部分完成',stopping:'正在停止',stopped:'已停止',cancelled:'已取消',error:'失败',failed:'失败',expired:'已过期',protocol_error:'协议错误',protocol_blocked:'协议受限',account_error:'账户已失效',unknown:'未知'};
function statusName(status){const key=String(status||'unknown').toLowerCase();return statusNames[key]||status||'未知'}
function formatDuration(seconds){const total=Math.max(0,Math.floor(Number(seconds)||0));const h=Math.floor(total/3600);const m=Math.floor((total%3600)/60);const s=total%60;return h>0?`${h}小时 ${String(m).padStart(2,'0')}分 ${String(s).padStart(2,'0')}秒`:`${String(m).padStart(2,'0')}分 ${String(s).padStart(2,'0')}秒`}
function taskElapsed(item,status){const start=Number(item.created_at||0);if(!start)return '--';const stopped=terminal(status)||['paused','cancelled','stopped'].includes(String(status||'').toLowerCase());const end=stopped?Number(item.updated_at||Date.now()/1000):Date.now()/1000;return formatDuration(end-start)}
function translateMessage(value){const text=String(value||'');let m;if((m=text.match(/^finished (\d+)\/(\d+) \(ok=(\d+) fail=(\d+), threads=(\d+)\)$/i)))return `批次完成 ${m[1]}/${m[2]}：成功 ${m[3]}，失败 ${m[4]}，并发 ${m[5]}`;if((m=text.match(/^running (\d+)\/(\d+) done \(ok=(\d+) fail=(\d+), threads=(\d+), inflight=(\d+)\)$/i)))return `批次处理中：完成 ${m[1]}/${m[2]}，成功 ${m[3]}，失败 ${m[4]}，当前处理 ${m[6]}`;if((m=text.match(/^imported via sso_to_auth_json \((\d+) account\(s\)\); probe ok=(\d+) fail=(\d+)/i)))return `本地保存 ${m[1]} 个账号，转换成功 ${m[2]}，失败 ${m[3]}`;if(text.startsWith('[chatgpt]'))return text.replace(/^\[chatgpt\]\s*/,'').replace(/:/g,'：');return text.replace(/^started; email=/i,'注册线程已启动，邮箱：').replace(/^queued; email=/i,'已创建邮箱并进入注册队列：').replace(/^visiting signup page$/i,'正在连接注册页面').replace(/^waiting for xAI verification code$/i,'验证码已发送，正在等待邮箱收信').replace(/^waiting for fresh xAI verification code$/i,'正在等待新的邮箱验证码').replace(/^sending email validation code$/i,'正在请求发送邮箱验证码').replace(/^code received: .*; verifying \+ creating immediately$/i,'已收到邮箱验证码，正在校验并创建账号').replace(/^fresh code received: .*$/i,'已收到新的邮箱验证码').replace(/^creating xAI account/i,'正在提交资料创建 xAI 账号').replace(/^solving Turnstile via (.+?) \(before email code\)$/i,'正在使用 $1 处理 Turnstile 验证').replace(/^Turnstile:\s*/i,'过盾进度：').replace(/^create_account HTTP \d+ accepted; extracting SSO.*$/i,'账号创建成功，正在提取 SSO').replace(/^RSC has no sso chain; CreateSession password fallback.*$/i,'未直接获得 SSO，正在尝试密码登录回退').replace(/^SSO obtained; converting via sso_to_auth_json.*$/i,'已获取 SSO，正在生成本地账号文件').replace(/^failed:\s*/i,'注册失败：').replace(/^starting ChatGPT registration/i,'正在启动 ChatGPT 浏览器注册').replace(/^launching browser/i,'正在启动浏览器').replace(/^session extracted/i,'已获取 ChatGPT 会话').replace(/^converting to auth/i,'正在生成认证文件').replace(/^registration complete/i,'ChatGPT 注册完成').replace(/^progress (\d+)\/(\d+)/i,'进度 $1/$2')}
const registrationFailureStatuses=new Set(['error','failed','protocol_error','protocol_blocked','account_error']);
function registrationCredentialReady(session){return (session.imported_account_ids||[]).length>0||Number(session.auth_json_count||0)>0}
function registrationSucceeded(session){const site=session.auto_import||{};if(site.enabled)return site.ok===true;return registrationCredentialReady(session)}
function registrationFailed(session){return registrationFailureStatuses.has(String(session.status||'').toLowerCase())&&!registrationCredentialReady(session)}
function registrationTotals(batches=[],sessions=[]){const batchIds=new Set();let ok=0,failed=0,inflight=0;for(const batch of batches){const id=String(batch.id||batch.batch_id||'');if(id)batchIds.add(id);const hasCounters=Object.prototype.hasOwnProperty.call(batch,'ok_count')&&Object.prototype.hasOwnProperty.call(batch,'fail_count');if(hasCounters){ok+=Math.max(0,Number(batch.ok_count)||0);failed+=Math.max(0,Number(batch.fail_count)||0)}else if(id){const rows=sessions.filter(session=>String(session.batch_id||'')===id);ok+=rows.filter(registrationCredentialReady).length;failed+=rows.filter(registrationFailed).length}inflight+=Math.max(0,Number(batch.inflight)||0)}for(const session of sessions){const batchId=String(session.batch_id||'');if(batchId&&batchIds.has(batchId))continue;if(registrationCredentialReady(session))ok+=1;else if(registrationFailed(session))failed+=1}return{ok,failed,inflight}}
function registrationTiming(batches,sessions,successCount){if(!successCount)return'总耗时 -- / 平均 --';const records=batches.length?batches:sessions;const starts=records.map(item=>Number(item.created_at||0)).filter(value=>value>0);if(!starts.length)return'总耗时 -- / 平均 --';const active=batches.some(batch=>!terminal(batch.status)&&!['paused','cancelled','stopped'].includes(String(batch.status||'').toLowerCase()));const ends=records.map(item=>Number(item.updated_at||item.created_at||0)).filter(value=>value>0);const total=Math.max(0,(active?Date.now()/1000:Math.max(...ends))-Math.min(...starts));return `总耗时 ${formatDuration(total)} / 平均 ${(total/successCount).toFixed(1)}秒`}
function metricRate(ok,fail){const total=ok+fail;return total?`${(ok*100/total).toFixed(1)}%`:'--'}
function activityTone(status){const key=String(status||'unknown').toLowerCase();if(registrationFailureStatuses.has(key)||key==='cancelled')return'failed';if(['imported','success','completed','done','probe_complete'].includes(key))return'success';if(['queued','starting','waiting_solver','waiting_email','import_queued','probe_queued','probe_retry_pending','probe_uncertain','paused','pausing'].includes(key))return'waiting';return'running'}
function activityTime(value){const date=new Date(Number(value||0)*1000);return Number.isNaN(date.getTime())?'--:--:--':date.toLocaleTimeString('zh-CN',{hour12:false})}
function sessionActions(session){const id=escapeHtml(session.id||'');const actions=[];const probeState=String(session.probe?.state||'').toLowerCase();if((Number(session.probe?.fail||0)>0||Number(session.probe?.uncertain||0)>0)&&!['running','retry_pending'].includes(probeState))actions.push(`<button class="retry-task" data-action="retry-probe" data-type="session" data-id="${id}">重试测活</button>`);if(session.auto_import?.ok===false&&!session.auto_import?.skipped&&String(session.status||'').toLowerCase()!=='auto_importing')actions.push(`<button class="retry-task" data-action="retry-import" data-type="session" data-id="${id}">重试导入</button>`);if(!session.batch_id&&!terminal(session.status))actions.push(`<button class="stop" data-action="stop" data-type="session" data-id="${id}">停止</button>`);return actions.join('')}
const chatgptFlowStepTemplate=[
  {key:'open',title:'打开 ChatGPT 官网'},
  {key:'email',title:'注册并输入邮箱'},
  {key:'password',title:'填写密码并继续'},
  {key:'verification',title:'获取注册验证码'},
  {key:'profile',title:'填写姓名和生日'},
  {key:'completion',title:'等待注册成功'},
  {key:'identity',title:'生成 Codex Agent Identity'},
  {key:'json',title:'转换 Agent Identity JSON'},
];
function chatgptImportTarget(session){const target=String(session?.auto_import?.target||config.auto_import_target||'sub2api').toLowerCase();return target==='cpa'?{key:'cpa',title:'导入 CPA Agent Identity'}:{key:'sub2api',title:'导入 Sub2API 并绑定分组'}}
function chatgptFlowSteps(session){return [...chatgptFlowStepTemplate,{key:'site',title:chatgptImportTarget(session).title}]}
function isChatgptSession(session){return String(session.id||'').startsWith('cgpt_')||String(session.adapter_build||'').includes('chatgpt')}
function flowHas(messages,pattern){return messages.some(message=>pattern.test(message))}
function chatgptFailureStep(session,messages){const error=String(session.error||session.message||'').toLowerCase();if(/sub2api|cpa|站点导入|导入失败|group|分组/.test(error))return 8;if(/json|认证文件|auth\.json/.test(error))return 7;if(/access.?token|session|agent identity|private key|agent 注册/.test(error))return 6;if(/account_deactivated|账户.*(?:删除|停用)|账号.*(?:删除|停用)/.test(error))return 3;if(/unsupported_email|email you provided is not supported|不支持当前邮箱/.test(error))return 1;if(/完成账号|资料|about-you|姓名|生日|年龄|profile/.test(error))return 4;if(/验证码|verification|\bcode\b/.test(error))return 3;if(/密码|password/.test(error))return 2;if(/邮箱|email|signup/.test(error))return 1;if(/注册完成|等待注册|completion|passkey|手机号/.test(error))return 5;for(let index=chatgptFlowStepTemplate.length-1;index>=0;index--){if(messages.some(message=>message.includes(`[chatgpt] ${chatgptFlowStepTemplate[index].key}`)))return index}return 0}
function buildChatgptWorkflow(session){
  if(!isChatgptSession(session))return null;
  const steps=chatgptFlowSteps(session);
  const messages=(session.events||[]).map(event=>String(event.message||'').toLowerCase());
  const states=steps.map(()=> 'pending');
  const reachedEmail=flowHas(messages,/\[chatgpt\] email:/);
  const emailDone=flowHas(messages,/\[chatgpt\] email: submitted/);
  const reachedPassword=flowHas(messages,/\[chatgpt\] password:/);
  const passwordDone=flowHas(messages,/\[chatgpt\] password: submitted/);
  const reachedVerification=flowHas(messages,/\[chatgpt\] verification:/);
  const reachedProfile=flowHas(messages,/\[chatgpt\] profile:/);
  const profileDone=flowHas(messages,/\[chatgpt\] profile: submitted/);
  const reachedCompletion=flowHas(messages,/\[chatgpt\] completion:/);
  const completionDone=flowHas(messages,/\[chatgpt\] completion: done/);
  const reachedIdentity=flowHas(messages,/正在注册 codex agent identity|codex agent identity 注册完成/);
  const identityDone=flowHas(messages,/codex agent identity 注册完成/);
  const reachedJson=flowHas(messages,/正在转换 auth\.json|agent identity auth\.json/);
  const jsonDone=flowHas(messages,/agent identity auth\.json 转换完成/);
  const reachedSite=flowHas(messages,/正在导入 (?:sub2api|cpa)|正在重新转换 agent identity json 并导入 (?:sub2api|cpa)/);
  const siteDone=Boolean(session.auto_import?.ok===true)||flowHas(messages,/(?:sub2api|cpa) 导入成功/);
  const siteRequired=Boolean(session.auto_import?.enabled);
  const succeeded=registrationSucceeded(session);
  if(messages.length)states[0]='running';
  if(reachedEmail)states[0]='done';
  if(reachedEmail)states[1]='running';
  if(emailDone)states[1]='done';
  if(reachedPassword)states[2]=passwordDone?'done':'running';
  else if(reachedVerification||reachedProfile||reachedCompletion||reachedIdentity)states[2]='skipped';
  if(reachedVerification)states[3]='running';
  if(reachedProfile||reachedCompletion||reachedIdentity)states[3]='done';
  if(reachedProfile)states[4]=profileDone?'running':'running';
  if(reachedCompletion||reachedIdentity)states[4]='done';
  if(reachedCompletion)states[5]=completionDone||reachedIdentity?'done':'running';
  if(reachedIdentity)states[6]=identityDone?'done':'running';
  if(reachedJson)states[7]=jsonDone?'done':'running';
  if(reachedSite)states[8]=siteDone?'done':'running';
  else if(jsonDone&&!siteRequired)states[8]='skipped';
  if(succeeded){for(let i=0;i<states.length;i++)if(states[i]==='pending'||states[i]==='running')states[i]='done'}
  let failedStep=-1;
  if(registrationFailed(session)){failedStep=chatgptFailureStep(session,messages);states[failedStep]='failed';for(let i=failedStep+1;i<states.length;i++)if(states[i]!=='done'&&states[i]!=='skipped')states[i]='pending'}
  const completed=states.filter(state=>state==='done'||state==='skipped').length;
  return {steps:steps.map((step,index)=>({...step,state:states[index],number:index+1})),completed,total:steps.length,failedStep};
}
function workflowHtml(workflow){if(!workflow)return'';const summary=workflow.failedStep>=0?`第 ${workflow.failedStep+1} 步失败`:`${workflow.completed} / ${workflow.total}`;const rows=workflow.steps.map(step=>{const marks={done:'✓',skipped:'跳',running:'…',failed:'×',pending:''};return `<div class="flow-step ${step.state}"><span class="flow-number">${step.number}</span><span class="flow-title">${escapeHtml(step.title)}</span><span class="flow-mark">${marks[step.state]||''}</span></div>`}).join('');return `<div class="workflow-panel"><div class="workflow-head"><span>流程</span><strong>${escapeHtml(summary)}</strong></div>${rows}</div>`}
function buildActivities(batches,sessions){const items=[];const batchNames=new Map(batches.map((batch,index)=>[batch.id||batch.batch_id,`批次 ${index+1}`]));for(const batch of batches){items.push({key:`batch-${batch.id}`,at:Number(batch.updated_at||batch.created_at||0),status:batch.status,title:`${batchNames.get(batch.id||batch.batch_id)||'注册批次'} · ${batch.count||0} 个账号`,message:translateMessage(batch.message||statusName(batch.status)),actions:'',meta:`${statusName(batch.status)} · 用时 ${taskElapsed(batch,batch.status)}`})}for(const session of sessions){const events=Array.isArray(session.events)&&session.events.length?session.events:[{at:session.updated_at||session.created_at,status:session.status,message:session.message||session.error||statusName(session.status)}];events.forEach((event,index)=>{const current=index===events.length-1;const batchName=session.batch_id?batchNames.get(session.batch_id):'';const prefix=session.batch_index?`#${session.batch_index} `:'';const title=`${prefix}${session.email||'注册账号'}${batchName?` · ${batchName}`:''}`;let message=translateMessage(event.message||statusName(event.status));if(current&&session.error&&registrationFailed(session)&&!message.includes(session.error))message=`${message}；${session.error}`;const queue=current&&Number(session.pipeline_queue?.position||0)>0?` · 排队第 ${session.pipeline_queue.position} 位`:'';items.push({key:`${session.id}-${index}-${event.at}`,at:Number(event.at||session.updated_at||0),status:event.status||session.status,title,message,actions:current?sessionActions(session):'',meta:`${statusName(event.status||session.status)}${queue}`,workflow:current?buildChatgptWorkflow(session):null})})}return items.sort((a,b)=>a.at-b.at).slice(-160)}
function activityHtml(item){const tone=activityTone(item.status);return `<div class="activity-item ${tone}"><div class="activity-top"><div class="activity-title">${escapeHtml(item.title)}</div><time class="activity-time">${escapeHtml(activityTime(item.at))}</time></div><div class="activity-message">${escapeHtml(item.message)}</div>${workflowHtml(item.workflow)}<div class="activity-meta"><span class="activity-status">${escapeHtml(item.meta)}</span>${item.actions?`<div class="activity-actions">${item.actions}</div>`:''}</div></div>`}
function updateRegistrationPauseButton(batches){const button=document.querySelector('#pause-current');const running=batches.filter(batch=>!terminal(batch.status)&&!['paused','pausing'].includes(String(batch.status||'').toLowerCase()));const paused=batches.filter(batch=>['paused','cancelled','stopped'].includes(String(batch.status||'').toLowerCase()));button.classList.toggle('resume',running.length===0&&paused.length>0);button.dataset.mode=running.length?'pause':paused.length?'resume':'';button.textContent=running.length?'暂停注册':paused.length?'继续注册':'暂停注册';button.disabled=running.length===0&&paused.length===0}
function updatePauseButton(batches){if(activeConfigModule==='probe')updateProbePauseButton(batches);else updateRegistrationPauseButton(batches)}
function selectedProbeBatch(batches=monitorState.batches){const id=document.querySelector('#probe-batch')?.value;return batches.find(batch=>String(batch.id||batch.batch_id||'')===id)}
function updateProbePauseButton(batches=[]){const button=document.querySelector('#pause-current');const batch=selectedProbeBatch(batches);const state=String(batch?.probe_status||'').toLowerCase();const active=['queued','running','paused'].includes(state);button.classList.toggle('resume',state==='paused');button.dataset.mode=state==='paused'?'resume-probe':active?'pause-probe':'';button.textContent=state==='paused'?'继续测活':'暂停测活';button.disabled=!active}
function renderMonitor(batches,sessions){monitorState={batches,sessions};updatePauseButton(batches);const registration=registrationTotals(batches,sessions);const regOk=registration.ok;const regFail=registration.failed;let importOk=0,importFail=0,probeOk=0,probeFail=0;for(const session of sessions){const item=session.auto_import||{};if(item.enabled&&item.ok===true)importOk+=Number(item.imported||1);if(item.enabled&&item.ok===false&&!item.skipped)importFail+=Number(item.failed||1);probeOk+=Number(session.probe?.ok||0);probeFail+=Number(session.probe?.fail||0)}document.querySelector('#stat-register-ok').textContent=regOk;document.querySelector('#stat-register-fail').textContent=regFail;document.querySelector('#stat-register-rate').textContent=metricRate(regOk,regFail);document.querySelector('#stat-import-ok').textContent=importOk;document.querySelector('#stat-import-fail').textContent=importFail;document.querySelector('#stat-import-rate').textContent=metricRate(importOk,importFail);document.querySelector('#stat-probe-ok').textContent=probeOk;document.querySelector('#stat-probe-fail').textContent=probeFail;document.querySelector('#stat-probe-rate').textContent=metricRate(probeOk,probeFail);const activities=buildActivities(batches,sessions);document.querySelector('#activity-count').textContent=`${activities.length} 条`;document.querySelector('#summary').textContent=batches.length||sessions.length?`${batches.length} 个批次，${sessions.length} 个账号会话 · ${registrationTiming(batches,sessions,regOk)}`:'暂无任务';const feed=document.querySelector('#tasks');const follow=feed.dataset.ready!=='1'||feed.scrollHeight-feed.scrollTop-feed.clientHeight<72;feed.innerHTML=activities.length?activities.map(activityHtml).join(''):'<div class="activity-empty">启动任务后会在这里逐步显示注册动态</div>';feed.dataset.ready='1';if(follow)requestAnimationFrame(()=>{feed.scrollTop=feed.scrollHeight})}
function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function rotationDate(value){const timestamp=Number(value||0);if(!timestamp)return'--';return new Date(timestamp*1000).toLocaleString('zh-CN',{hour12:false}).replace(/\//g,'-')}
function rotationDuration(start,end){const from=Number(start||0);const to=Number(end||0);if(!from||!to||to<from)return'--';let minutes=Math.max(1,Math.floor((to-from)/60));const days=Math.floor(minutes/1440);minutes-=days*1440;const hours=Math.floor(minutes/60);minutes-=hours*60;if(days)return`${days}天${hours}小时${minutes}分钟`;if(hours)return`${hours}小时${minutes}分钟`;return`${minutes}分钟`}
function rotationStatusName(status){return String(status||'').toLowerCase()==='error'?'错误':'正常'}
function rotationTypeName(type){return String(type||'').toLowerCase()==='chatgpt'?'ChatGPT':'xAI'}
function rotationScheduleText(poll={}){const next=Number(poll.next_auto_run_at||0);const last=Number(poll.last_auto_run_at||0);const nextText=next?`下次自动轮询：${rotationDate(next)}`:'每 30 分钟自动全量探活';const lastText=last?` · 上次自动轮询：${rotationDate(last)}`:'';return `${poll.running?'正在执行全量探活 · ':''}${nextText}${lastText}`}
