  const siteReached=/auto_import|正在执行队列导入|正在手动重试导入|队列导入完成|手动导入完成|导入 .*sub2api|导入 .*cpa|绑定分组/.test(all);
  const siteDone=session.auto_import?.ok===true||/队列导入完成：成功 [1-9]\d*，失败 0|手动导入完成：成功 [1-9]\d*，失败 0/.test(all);
  if(messages.length)states[0]='running';
  if(/\[xai\] navigate: ready|\[xai\] signup_method:/.test(all))states[0]='done';
  if(/\[xai\] signup_method:/.test(all))states[1]='running';
  if(/\[xai\] signup_method: selected|\[xai\] email:/.test(all))states[1]='done';
  if(/\[xai\] email:|\[xai\] password:|\[xai\] profile:/.test(all))states[2]='running';
  if(/\[xai\] verification:|\[xai\] completion:/.test(all))states[2]='done';
  if(/\[xai\] verification:/.test(all))states[3]='running';
  if(/\[xai\] completion: done|原始浏览器 session/.test(all))states[3]='done';
  if(/\[xai\] completion:/.test(all))states[4]='running';
  if(/原始浏览器 session|浏览器注册成功/.test(all))states[4]='done';
  if(/原始浏览器 session|浏览器注册成功/.test(all))states[5]='running';
  if(/正在浏览器中完成.*oauth|\[xai\] oauth:/.test(all))states[5]='done';
  if(/\[xai\] oauth:|浏览器 oauth/.test(all))states[6]='running';
  if(/\[xai\] oauth: approved|auth 转换完成/.test(all))states[6]='done';
  if(/\[xai\] oauth: approved|auth 转换完成/.test(all))states[7]='running';
  if(jsonReady)states[7]='done';
  if(siteReached)states[8]=siteDone?'done':'running';
  else if(jsonReady&&!siteRequired)states[8]='skipped';
  const succeeded=registrationSucceeded(session)||Boolean((session.imported_accounts||[]).length);
  if(succeeded){for(let index=0;index<8;index+=1)if(states[index]==='pending'||states[index]==='running')states[index]='done';if(!siteRequired)states[8]='skipped';else if(siteDone)states[8]='done'}
  let failedStep=-1;
