  if(registrationFailed(session)){
    const error=String(session.error||session.message||'').toLowerCase();
    if(/import|导入|group|分组/.test(error))failedStep=8;
    else if(/device|auth|认证|token|json|转换/.test(error))failedStep=7;
    else if(/oauth|授权/.test(error))failedStep=6;
    else if(/sso|session|会话/.test(error))failedStep=5;
    else if(/create|创建账号|signup/.test(error))failedStep=4;
    else if(/code|验证码/.test(error))failedStep=3;
    else if(/email|邮箱|password|密码|profile|资料/.test(error))failedStep=2;
    else failedStep=Math.max(0,states.findLastIndex(state=>state==='running'));
    states[failedStep]='failed';
  }
