function updateDownloadBatches(batches){const select=document.querySelector('#download-batch');const current=select.value;select.innerHTML='<option value="">全部成功账号</option>'+batches.map((b,index)=>`<option value="${escapeHtml(b.id||b.batch_id||'')}">批次 ${index+1} · ${b.count||0} 个 · 成功 ${b.ok_count||b.imported||0}</option>`).join('');if([...select.options].some(o=>o.value===current))select.value=current}
function updateProbeBatches(batches=[]){const select=document.querySelector('#probe-batch');if(!select)return;const current=select.value;const target=form.elements.namedItem('registration_target').value;const filtered=batches.filter(batch=>{const id=String(batch.id||batch.batch_id||'');return target==='chatgpt'?id.startsWith('batch_cgpt_'):id.startsWith('batch_')&&!id.startsWith('batch_cgpt_')});select.innerHTML=filtered.length?filtered.map((batch,index)=>{const id=String(batch.id||batch.batch_id||'');const count=Number(batch.count||(batch.session_ids||[]).length||0);return `<option value="${escapeHtml(id)}">${target==='chatgpt'?'ChatGPT':'Grok'} 批次 ${index+1} · ${count} 个账号</option>`}).join(''):'<option value="">暂无可测活批次</option>';select.disabled=!filtered.length;if(filtered.some(batch=>String(batch.id||batch.batch_id||'')===current))select.value=current;if(activeConfigModule==='probe'){document.querySelector('#start').disabled=!filtered.length;updateProbePauseButton(batches)}}
async function startBatchProbe(){const select=document.querySelector('#probe-batch');const button=document.querySelector('#start');const batchId=select.value;if(!batchId){notify('当前注册目标没有可测活批次');return}button.disabled=true;button.textContent='正在提交…';try{const result=await api(`/api/batches/${encodeURIComponent(batchId)}/retry-probe`,{method:'POST'});notify(result.scheduled?`批次测活已启动：${result.scheduled} 个账号`:'该批次没有可测活账号');await refresh()}catch(e){notify(`开始测活失败：${e.message}`)}finally{button.textContent=activeConfigModule==='probe'?'开始测活':'开始注册';button.disabled=false}}
async function togglePauseProbe(){const button=document.querySelector('#pause-current');const batch=selectedProbeBatch();const mode=button.dataset.mode;if(!batch||!mode)return;button.disabled=true;button.textContent=mode==='pause-probe'?'正在暂停…':'正在继续…';try{await api(`/api/batches/${encodeURIComponent(batch.id||batch.batch_id)}/${mode}`,{method:'POST'});notify(mode==='pause-probe'?'测活已暂停，正在执行的请求会自然结束':'测活已继续');await refresh()}catch(e){notify(`${mode==='pause-probe'?'暂停':'继续'}测活失败：${e.message}`)}finally{updateProbePauseButton(monitorState.batches)}}
async function refresh(){try{const local=form.elements.namedItem('mail_provider').value==='hotmail_local';const [r,pool]=await Promise.all([api('/api/sessions'),local?api('/api/mail/hotmail/accounts'):Promise.resolve(null)]);const batches=r.batches||[];const sessions=r.sessions||[];updateDownloadBatches(batches);updateProbeBatches(batches);renderMonitor(batches,sessions);if(pool)renderHotmailAccounts(pool);if(activeConfigModule==='rotation')await refreshRotation()}catch(e){notify(`刷新失败：${e.message}`)}}
async function togglePauseCurrent(){if(activeConfigModule==='probe'){await togglePauseProbe();return}const button=document.querySelector('#pause-current');const mode=button.dataset.mode;const statuses=mode==='pause'?batch=>!terminal(batch.status)&&!['paused','pausing'].includes(String(batch.status||'').toLowerCase()):batch=>['paused','cancelled','stopped'].includes(String(batch.status||'').toLowerCase());const targets=monitorState.batches.filter(statuses);if(!mode||!targets.length)return;button.disabled=true;button.textContent=mode==='pause'?'正在暂停…':'正在继续…';try{const results=await Promise.allSettled(targets.map(batch=>api(`/api/batches/${batch.id||batch.batch_id}/${mode}`,{method:'POST'})));const ok=results.filter(result=>result.status==='fulfilled').length;notify(`${mode==='pause'?'暂停':'继续'}请求已提交：${ok}/${targets.length} 个批次`);await refresh()}catch(e){notify(`${mode==='pause'?'暂停':'继续'}失败：${e.message}`)}finally{updatePauseButton(monitorState.batches)}}
function clearMonitorLogs(){logClearBefore=Date.now()/1000;renderedLogSignature='';renderLog([]);notify('当前显示的日志已清空，新日志会继续追加')}
async function resetRound(){if(!window.confirm('确定清除本轮监控任务吗？\n\n已生成的账号文件不会删除，但清除后无法继续当前暂停批次。'))return;const button=document.querySelector('#reset-round');button.disabled=true;try{const result=await api('/api/sessions/reset',{method:'POST'});notify(`本轮任务已清除：${result.batches_cleared||0} 个批次，${result.sessions_cleared||0} 个会话`);await refresh()}catch(e){notify(`清除失败：${e.message}`)}finally{button.disabled=false}}
async function downloadAccounts(){const button=document.querySelector('#download-accounts');const format=document.querySelector('#download-format').value;const batch=document.querySelector('#download-batch').value;button.disabled=true;button.textContent='正在生成…';try{const params=new URLSearchParams({format});if(batch)params.set('batch_id',batch);const response=await fetch(`/api/download?${params}`);if(!response.ok){let detail=`HTTP ${response.status}`;try{const body=await response.json();detail=body.detail||detail}catch{}throw new Error(detail)}const blob=await response.blob();const disposition=response.headers.get('Content-Disposition')||'';const match=disposition.match(/filename="([^"]+)"/);const jsonFormat=['json','cpa_json','sub2api_json','chatgpt_auth_json'].includes(format);const filename=match?.[1]||`progrok_accounts.${jsonFormat?'json':'txt'}`;const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);notify(`已下载 ${response.headers.get('X-ProGrok-Account-Count')||''} 个账号`)}catch(e){notify(`下载失败：${e.message}`)}finally{button.disabled=false;button.textContent='下载账号'}}
document.querySelector('#tasks').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;b.disabled=true;const action=b.dataset.action||'stop';try{const result=await api(`/api/${b.dataset.type==='batch'?'batches':'sessions'}/${b.dataset.id}/${action}`,{method:'POST'});const messages={pause:'已发送暂停请求',resume:'批次已继续','retry-probe':`已安排 ${result.scheduled??1} 个账号重试测活`,'retry-import':`已安排 ${result.scheduled??1} 个账号重试导入`,stop:'已发送停止请求'};notify(messages[action]||'操作已提交');await refresh()}catch(err){notify(err.message)}finally{b.disabled=false}});
document.querySelector('#paths-button').addEventListener('click',()=>togglePaths());document.querySelector('#paths-close').addEventListener('click',()=>{document.querySelector('#paths-popover').hidden=true});document.querySelector('#paths-list').addEventListener('click',e=>{const b=e.target.closest('.copy-path');if(b)copyOutputPath(Number(b.dataset.index))});document.querySelector('#download-button').addEventListener('click',toggleDownload);document.querySelector('#download-close').addEventListener('click',()=>{document.querySelector('#download-popover').hidden=true});document.querySelector('#download-accounts').addEventListener('click',downloadAccounts);document.querySelector('#pause-current').addEventListener('click',togglePauseCurrent);document.querySelector('#detect-proxy').addEventListener('click',()=>detectProxy(true,false));form.elements.namedItem('mail_provider').addEventListener('change',switchMailProvider);form.elements.namedItem('auto_import_target').addEventListener('change',syncFormatFromTarget);form.elements.namedItem('registration_json_format').addEventListener('change',syncTargetFromFormat);form.elements.namedItem('sub2api_auth_mode').addEventListener('change',updateImportTargetFields);document.addEventListener('click',e=>{const paths=document.querySelector('#paths-popover');const download=document.querySelector('#download-popover');if(!paths.hidden&&!e.target.closest('.path-control'))paths.hidden=true;if(!download.hidden&&!e.target.closest('.download-control'))download.hidden=true});
document.querySelector('#test-hotmail-helper').addEventListener('click',testHotmailHelper);document.querySelector('#import-hotmail-accounts').addEventListener('click',importHotmailAccounts);document.querySelector('#probe-hotmail-accounts').addEventListener('click',probeAllHotmailAccounts);document.querySelector('#delete-used-hotmail-accounts').addEventListener('click',deleteUsedHotmailAccounts);document.querySelector('#hotmail-account-list').addEventListener('click',handleHotmailAccountAction);
