document.querySelector('#clear-logs').addEventListener('click',clearMonitorLogs);
document.querySelector('#probe-batch').addEventListener('change',()=>updateProbePauseButton(monitorState.batches));
let rotationKeywordTimer=0;
document.querySelector('#rotation-search-button').addEventListener('click',()=>{rotationState.selected.clear();refreshRotation({page:1})});
document.querySelector('#rotation-status').addEventListener('change',()=>{rotationState.selected.clear();refreshRotation({page:1})});
document.querySelector('#rotation-page-size').addEventListener('change',()=>{rotationState.selected.clear();refreshRotation({page:1})});
document.querySelector('#rotation-keyword').addEventListener('input',()=>{clearTimeout(rotationKeywordTimer);rotationKeywordTimer=setTimeout(()=>{rotationState.selected.clear();refreshRotation({page:1})},280)});
document.querySelector('#rotation-keyword').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();rotationState.selected.clear();refreshRotation({page:1})}});
document.querySelector('#rotation-prev').addEventListener('click',()=>refreshRotation({page:Math.max(1,rotationState.page-1)}));
document.querySelector('#rotation-next').addEventListener('click',()=>refreshRotation({page:Math.min(rotationState.pages,rotationState.page+1)}));
document.querySelector('#rotation-select-all').addEventListener('change',event=>{const checked=event.target.checked;rotationState.items.forEach(item=>{if(checked)rotationState.selected.add(item.id);else rotationState.selected.delete(item.id)});updateRotationSelection()});
document.querySelector('#rotation-list').addEventListener('change',event=>{const checkbox=event.target.closest('[data-rotation-select]');if(!checkbox)return;if(checkbox.checked)rotationState.selected.add(checkbox.dataset.rotationSelect);else rotationState.selected.delete(checkbox.dataset.rotationSelect);updateRotationSelection()});
document.querySelector('#rotation-list').addEventListener('click',async event=>{const button=event.target.closest('[data-rotation-action]');if(!button)return;const id=button.dataset.id;button.disabled=true;try{if(button.dataset.rotationAction==='probe')await requestRotationProbe([id]);else await deleteRotationRecords([id])}catch(error){notify(`操作失败：${error.message}`)}finally{button.disabled=false}});
document.querySelector('#rotation-probe-selected').addEventListener('click',async()=>{const button=document.querySelector('#rotation-probe-selected');button.disabled=true;try{await requestRotationProbe(selectedRotationIds())}catch(error){notify(`探活启动失败：${error.message}`)}finally{updateRotationSelection()}});
document.querySelector('#rotation-delete-selected').addEventListener('click',async()=>{const button=document.querySelector('#rotation-delete-selected');button.disabled=true;try{await deleteRotationRecords(selectedRotationIds())}catch(error){notify(`删除失败：${error.message}`)}finally{updateRotationSelection()}});
