form.addEventListener('submit',start);document.querySelector('#save').addEventListener('click',save);document.querySelector('#reset-round').addEventListener('click',resetRound);document.querySelector('#refresh').addEventListener('click',refresh);document.querySelector('#detect-solver').addEventListener('click',()=>detectSolver(true));let initialConfigModule='registration';try{initialConfigModule=localStorage.getItem(configModuleKey)||'registration'}catch{}setActiveConfigModule(initialConfigModule,false);load();setInterval(refresh,1000);setInterval(checkHealth,15000);setInterval(()=>detectSolver(false),10000);
